import{_ as n,C as t,o as s,c as o,j as a,a as r,E as l,al as c}from"./chunks/framework.7vp1BMOE.js";const b=JSON.parse('{"title":"Asset Tracking","description":"","frontmatter":{},"headers":[],"relativePath":"ko/debug/asset_tracking.md","filePath":"ko/debug/asset_tracking.md"}'),d={name:"ko/debug/asset_tracking.md"};function p(h,e,m,u,g,f){const i=t("Badge");return s(),o("div",null,[e[0]||(e[0]=a("h1",{id:"asset-tracking",tabindex:"-1"},[r("Asset Tracking "),a("a",{class:"header-anchor",href:"#asset-tracking","aria-label":'Permalink to "Asset Tracking"'},"​")],-1)),l(i,{type:"tip",text:"PX4 v1.18"}),e[1]||(e[1]=c(`<p>PX4 can track and log detailed information about external hardware devices connected to the flight controller. This enables unique identification of vehicle parts throughout their operational lifetime using device IDs, serial numbers, and version information.</p><div class="info custom-block"><p class="custom-block-title">INFO</p><p>Asset tracking is currently implemented for <a href="./../dronecan/">DroneCAN</a> devices only.</p></div><h2 id="개요" tabindex="-1">개요 <a class="header-anchor" href="#개요" aria-label="Permalink to &quot;개요&quot;">​</a></h2><p>Asset tracking allows you to determine exactly which hardware is installed on a vehicle, providing serial number, version, and other information. This makes it easier to track and maintain specific vehicle parts across multiple vehicles, to quickly see what versions you&#39;re running when debugging, and log component information for regulatory audits.</p><p>Asset tracking automatically collects and logs the following metadata from external devices:</p><ul><li><strong>Device identification</strong>: Vendor name, model name, device type</li><li><strong>Version information</strong>: Firmware version, hardware version</li><li><strong>Unique identifiers</strong>: Serial number, device ID</li><li><strong>Device capabilities</strong>: ESC, GPS, magnetometer, barometer, etc.</li></ul><p>This information is published via the <a href="./../msg_docs/DeviceInformation"><code>device_information</code></a> uORB topic and logged to flight logs. This enables fleet management, maintenance tracking, and troubleshooting.</p><h2 id="viewing-device-information" tabindex="-1">Viewing Device Information <a class="header-anchor" href="#viewing-device-information" aria-label="Permalink to &quot;Viewing Device Information&quot;">​</a></h2><h3 id="real-time-monitoring" tabindex="-1">Real-Time Monitoring <a class="header-anchor" href="#real-time-monitoring" aria-label="Permalink to &quot;Real-Time Monitoring&quot;">​</a></h3><p>You can view device information in real-time using the <a href="./../debug/mavlink_shell">MAVLink Shell</a> or console:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">listener</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> device_information</span></span></code></pre></div><p>Example output for a CAN GPS module:</p><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>TOPIC: device_information</span></span>
<span class="line"><span> device_information</span></span>
<span class="line"><span>    timestamp: 16258961403 (0.216525 seconds ago)</span></span>
<span class="line"><span>    device_id: 8944643 (Type: 0x88, UAVCAN:0 (0x7C))</span></span>
<span class="line"><span>    device_type: 5</span></span>
<span class="line"><span>    vendor_name: &quot;cubepilot&quot;</span></span>
<span class="line"><span>    model_name: &quot;here4&quot;</span></span>
<span class="line"><span>    firmware_version: &quot;1.14.3006590&quot;</span></span>
<span class="line"><span>    hardware_version: &quot;4.19&quot;</span></span>
<span class="line"><span>    serial_number: &quot;1c00410018513331&quot;</span></span></code></pre></div><p>Device information is published in a round-robin fashion for each detected device, at a rate of approximately 1 Hz.</p><h3 id="multi-capability-devices" tabindex="-1">Multi-Capability Devices <a class="header-anchor" href="#multi-capability-devices" aria-label="Permalink to &quot;Multi-Capability Devices&quot;">​</a></h3><p>Devices with multiple sensors (e.g., a CAN GPS/magnetometer combo module like the HERE4) register separate device information entries for each capability. Each entry shares the same serial number and base metadata but has a different <code>device_id</code> corresponding to the specific sensor capability.</p><h2 id="비행-로그-분석" tabindex="-1">비행 로그 분석 <a class="header-anchor" href="#비행-로그-분석" aria-label="Permalink to &quot;비행 로그 분석&quot;">​</a></h2><p>Device information is automatically logged to flight logs. You can extract it using <a href="./../log/flight_log_analysis#pyulog">pyulog</a>, though note that fields like vendor name, model name, and serial number are stored as <code>char</code> arrays and require additional parsing.</p><h2 id="see-also" tabindex="-1">See Also <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;See Also&quot;">​</a></h2><ul><li><a href="./../can/">CAN (DroneCAN &amp; Cyphal)</a> — CAN bus configuration and setup</li><li><a href="./../dronecan/">DroneCAN</a> — DroneCAN-specific documentation</li><li><a href="./../log/flight_log_analysis">Flight Log Analysis</a> — Flight log analysis</li></ul>`,20))])}const k=n(d,[["render",p]]);export{b as __pageData,k as default};
